from __future__ import annotations

import heapq
import math
from typing import Iterable, List, Sequence, Tuple

Circle = Tuple[float, float, float]

_GREEDY_LIMIT = 64
_SEARCH_TOLERANCE = 1e-7
_MIN_CELL_HALF = 1e-6
_POLISH_STEP = 0.0625
_RADIUS_SHRINK = 1e-12
_DIAGONAL_FACTOR = math.sqrt(2.0)
_DIRECTIONS = (
    (-1.0, -1.0),
    (-1.0, 0.0),
    (-1.0, 1.0),
    (0.0, -1.0),
    (0.0, 1.0),
    (1.0, -1.0),
    (1.0, 0.0),
    (1.0, 1.0),
)

_CACHE: dict[int, tuple[Circle, ...]] = {1: ((0.5, 0.5, 0.5),)}
_GREEDY_PREFIX: List[Circle] = [(0.5, 0.5, 0.5)]


def _clearance(x: float, y: float, circles: Sequence[Circle]) -> float:
    clearance = min(x, y, 1.0 - x, 1.0 - y)
    for cx, cy, cr in circles:
        gap = math.hypot(x - cx, y - cy) - cr
        if gap < clearance:
            clearance = gap
    return clearance


def _coarse_best_seed(circles: Sequence[Circle]) -> tuple[float, float, float]:
    grid = 7 if len(circles) < 8 else 9
    best_x = 0.5
    best_y = 0.5
    best_clearance = _clearance(best_x, best_y, circles)
    inv = 1.0 / grid
    for ix in range(grid):
        x = (ix + 0.5) * inv
        for iy in range(grid):
            y = (iy + 0.5) * inv
            clearance = _clearance(x, y, circles)
            if clearance > best_clearance:
                best_x = x
                best_y = y
                best_clearance = clearance
    return best_x, best_y, best_clearance


def _polish_center(x: float, y: float, circles: Sequence[Circle]) -> tuple[float, float, float]:
    best_x = x
    best_y = y
    best_clearance = _clearance(x, y, circles)
    step = _POLISH_STEP
    while step > _MIN_CELL_HALF:
        improved = False
        for dx, dy in _DIRECTIONS:
            candidate_x = min(1.0, max(0.0, best_x + dx * step))
            candidate_y = min(1.0, max(0.0, best_y + dy * step))
            clearance = _clearance(candidate_x, candidate_y, circles)
            if clearance > best_clearance:
                best_x = candidate_x
                best_y = candidate_y
                best_clearance = clearance
                improved = True
        if not improved:
            step *= 0.5
    return best_x, best_y, best_clearance


def _find_next_circle(circles: Sequence[Circle]) -> Circle:
    best_x, best_y, best_clearance = _coarse_best_seed(circles)

    root_clearance = _clearance(0.5, 0.5, circles)
    heap: list[tuple[float, float, float, float, float]] = [
        (-(root_clearance + 0.5 * _DIAGONAL_FACTOR), 0.5, 0.5, 0.5, root_clearance)
    ]

    while heap:
        neg_upper_bound, half, center_x, center_y, _ = heapq.heappop(heap)
        upper_bound = -neg_upper_bound
        if upper_bound <= best_clearance + _SEARCH_TOLERANCE:
            break

        child_half = half * 0.5
        if child_half <= _MIN_CELL_HALF:
            continue

        for offset_x in (-child_half, child_half):
            child_x = center_x + offset_x
            for offset_y in (-child_half, child_half):
                child_y = center_y + offset_y
                clearance = _clearance(child_x, child_y, circles)
                if clearance > best_clearance:
                    best_x = child_x
                    best_y = child_y
                    best_clearance = clearance
                child_upper = clearance + child_half * _DIAGONAL_FACTOR
                if child_upper > best_clearance + _SEARCH_TOLERANCE:
                    heapq.heappush(
                        heap,
                        (-child_upper, child_half, child_x, child_y, clearance),
                    )

    best_x, best_y, best_clearance = _polish_center(best_x, best_y, circles)
    if best_clearance <= 0.0:
        raise RuntimeError("Could not place another positive-radius circle.")

    shrink = _RADIUS_SHRINK if best_clearance > 1e-9 else best_clearance * 1e-6
    radius = best_clearance - shrink
    if radius <= 0.0:
        radius = best_clearance * 0.5
    return (best_x, best_y, radius)


def _grid_layout(n: int) -> tuple[Circle, ...]:
    cols = math.ceil(math.sqrt(n))
    rows = math.ceil(n / cols)
    radius = 0.5 * min(1.0 / cols, 1.0 / rows)
    circles: list[Circle] = []
    for index in range(n):
        row = index // cols
        col = index % cols
        x = (col + 0.5) / cols
        y = (row + 0.5) / rows
        circles.append((x, y, radius))
    return tuple(circles)


def _validate_layout(circles: Sequence[Circle], n: int) -> None:
    if len(circles) != n:
        raise AssertionError(f"Expected {n} circles, got {len(circles)}")
    for index, (x, y, r) in enumerate(circles):
        if not math.isfinite(x) or not math.isfinite(y) or not math.isfinite(r):
            raise AssertionError(f"Circle #{index} contains non-finite values.")
        if r <= 0.0:
            raise AssertionError(f"Circle #{index} has non-positive radius {r!r}.")
        if x < r or x > 1.0 - r or y < r or y > 1.0 - r:
            raise AssertionError(f"Circle #{index} is not contained in the unit square.")
    for i in range(n - 1):
        xi, yi, ri = circles[i]
        for j in range(i + 1, n):
            xj, yj, rj = circles[j]
            if math.hypot(xj - xi, yj - yi) < ri + rj:
                raise AssertionError(f"Circles {i} and {j} overlap.")


def _extend_greedy_cache(target_n: int) -> None:
    while len(_GREEDY_PREFIX) < target_n:
        _GREEDY_PREFIX.append(_find_next_circle(_GREEDY_PREFIX))
        layout = tuple(_GREEDY_PREFIX)
        _validate_layout(layout, len(layout))
        _CACHE[len(layout)] = layout


def pack_circles(n: int = 26) -> Iterable[Tuple[float, float, float]]:
    if n <= 0:
        raise ValueError("n must be a positive integer.")

    cached = _CACHE.get(n)
    if cached is not None:
        return cached

    if n <= _GREEDY_LIMIT:
        _extend_greedy_cache(n)
        return _CACHE[n]

    layout = _grid_layout(n)
    _validate_layout(layout, n)
    _CACHE[n] = layout
    return layout
